mod core;mod packet;mod sparse;mod action;mod geometry;mod index;mod verifier;mod reference;mod qualify;mod build_packet;mod cost;
#[path="../source-phases/phase.rs"]mod phase;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng,instance::factor_base};
fn run(c:&Curve,pt:(u64,u64),d:&Div,t:&Div,ell:u64,sm:u64,gate:bool)->Vec<core::Trace>{let mut out=vec![];for seed in 1..=3{let tr=core::solve(c,pt,d,t,ell,sm,seed,gate,true);let done=tr.answer.is_some();out.push(tr);if done{break}}out}
fn add(a:&counted::Counts,b:&counted::Counts)->counted::Counts{let mut out=a.clone();for(m,v)in b{let w=out.entry(*m).or_default();for j in 0..16{w[j]+=v[j]}}out}
fn emit(p:u64,sm:u64,case:usize,rep:usize,name:&str,c:&counted::Counts){for(m,v)in c{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{name}\t{m}\t{}",v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}}
fn main(){counted::disable();geometry::controls();geometry::repeated_control();action::controls();let old:Vec<Vec<&str>>=include_str!("../root-pipeline/CONTROL.tsv").lines().skip(1).map(|l|l.split('\t').collect()).collect();let mut calls=0;println!("p\tsm\tcase\trep\tphase\tmodulus\tcounts");for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let expected=1+rng.below(ell-1);let t=c.mul(&d,expected);let diagnostic=run(&c,pt,&d,&t,ell,sm,true);let mut first=None;for rep in 0..2{counted::reset();let traces=run(&c,pt,&d,&t,ell,sm,false);let producer=counted::snapshot();counted::disable();let external=cost::snapshot();assert_eq!(traces,diagnostic);let trace_prefix=format!("TRACE\tp={p}\tsm={sm}\tcase={case}\tattempts=");let trace_prior=include_str!("../lazy-certificate/CONTROL.txt").lines().find_map(|l|l.strip_prefix(&trace_prefix)).unwrap();assert_eq!(format!("{traces:?}"),trace_prior);let last=traces.last().unwrap();assert_eq!(last.answer.map(|x|x.1),Some(expected));for(m,v)in &producer{if *m==p{continue}let row=old.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]=="1"&&x[5]==m.to_string()).unwrap();let vv:Vec<u64>=row[12].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(v.as_slice(),vv.as_slice());}
 counted::reset();let full=build_packet::build(&c,&d,&t,ell,sm,last);let mut cert=full.clone();let keep:Vec<_>=full.witness.iter().enumerate().filter(|(_,w)|**w!=0).map(|(i,&w)|(full.rows[i].clone(),w)).collect();cert.rows=keep.iter().map(|x|x.0.clone()).collect();cert.witness=keep.iter().map(|x|x.1).collect();assert!(!cert.rows.is_empty());let construction=counted::snapshot();counted::disable();let prefix=format!("CERT\tp={p}\tsm={sm}\tcase={case}\tpacket=");let prior=include_str!("../lazy-certificate/CONTROL.txt").lines().find_map(|l|l.strip_prefix(&prefix)).unwrap();assert_eq!(format!("{full:?}"),prior);if rep==0{eprintln!("SUPPORT\tp={p}\tsm={sm}\tcase={case}\tfull_rows={}\tkept_rows={}\tpacket={cert:?}",full.rows.len(),cert.rows.len());phase::reset();qualify::qualify(&cert);}phase::reset();counted::reset();assert!(verifier::verify(&cert));let checking=counted::snapshot();counted::disable();let phases=phase::snapshot();let mut sum=counted::Counts::new();for((_,m),v)in &phases{let w=sum.entry(*m).or_default();for j in 0..16{w[j]+=v[j]}}assert_eq!(sum,checking);
let prior_cost:Vec<Vec<&str>>=include_str!("../indexed-packet/CONTROL.tsv").lines().skip(1).map(|l|l.split('\t').collect()).collect();for(name,counts)in[("producer_with_native_control",&producer),("native_control",&external),("packet_construction",&construction)]{for(m,v)in counts{let prior=prior_cost.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]==name&&x[5]==m.to_string()).unwrap();let vv:Vec<u64>=prior[6].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(v.as_slice(),vv.as_slice());}}
let conservative=add
(&add(&producer,&construction),&checking);let mut candidate=conservative.clone();for(m,v)in &external{let w=candidate.get_mut(m).unwrap();for j in 0..16{w[j]-=v[j]}}
 let signature=(producer.clone(),external.clone(),construction.clone(),checking.clone(),candidate.clone(),phases.clone());if let Some(ref prev)=first{assert_eq!(prev,&signature)}else{first=Some(signature)}
 for(name,v)in[("producer_with_native_control",&producer),("native_control",&external),("packet_construction",&construction),("certificate_verifier",&checking),("conservative_total",&conservative),("derived_candidate_total",&candidate)]{emit(p,sm,case,rep,name,v)}for arm in[0,1]{let mut control=counted::Counts::new();for row in old.iter().filter(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]==arm.to_string()){let v:Vec<u64>=row[12].split(',').map(|x|x.parse().unwrap()).collect();control.insert(row[5].parse().unwrap(),v.try_into().unwrap());}assert_eq!(control.len(),2);emit(p,sm,case,rep,&format!("retained_arm{arm}"),&control)}for((name,m),v)in phases{emit(p,sm,case,rep,&format!("verify_{name}"),&counted::Counts::from([(m,v)]));}calls+=1;}}}}assert_eq!(calls,24);eprintln!("calls=24 original_targets=12 full_packet_replay_exact=true pruned_packet=true producer_subgroup_vectors_exact=true full_traces_exact=true producer_all_vectors_replay=true construction_vectors_replay=true native_group_diagnostics=true phase_sums_exact=true repeats_exact=true mutations_rejected_each_verifier=84 all_attempts_charged=true candidate=producer-minus-native-control-plus-construction-plus-verifier independent_verification=false");}
